dir:

































  &DefaultButton;




function dir$dmcnct(p){
  this.constructor(p);
}
dir$dmcnct.prototype = new DirEvent();
dir$dmcnct.prototype.afterInit = function(){
  var p = this._dir;
}
dir$dmcnct.prototype.afterInit = function(renderType){
  var p = this._dir,g = p.grid()

  dir$dmcnctDisabledMasterField(p, g);

}

function dir$dmcnctDisabledMasterField(p, g){

  if(p.valForm('ma_cnct').trim() != '')
  {
    p.setDisabled('ma_cnct', true);
  }
  else
  {
    p.setDisabled('ma_cnct', false);
  }
}








declare @codeExistsNewMsg nvarchar(256), @codeExistsEditMsg nvarchar(256)
select @codeExistsNewMsg = case when '@@lan' = 'v' then N'Mã chức năng chứng từ đã tồn tại' else N'The voucher function code already exists' end
select @codeExistsEditMsg = case when '@@lan' = 'v' then N'Mã chức năng chứng từ đã tồn tại' else N'The voucher function code already exists' end
